12	type Poller struct {
13		logger *zap.Logger
14	
15		interval time.Duration
16		notify   func(modified bool)
17	}
18	
19	func WithInterval(interval time.Duration) containers.Option[Poller] {
20		return func(p *Poller) {
21			p.interval = interval
22		}
23	}
24	
25	func WithNotify(t *testing.T, n func(modified bool)) containers.Option[Poller] {
26		t.Helper()
27		return func(p *Poller) {
28			p.notify = n
29		}
30	}
31	
32	func NewPoller(logger *zap.Logger, opts ...containers.Option[Poller]) *Poller {
33		p := &Poller{
34			logger:   logger,
35			interval: 30 * time.Second,
36		}
37		containers.ApplyAll(p, opts...)
38		return p
39	}
40	
41	// Poll is a utility function for a common polling strategy used by lots of declarative
42	// store implementations.
43	func (p *Poller) Poll(ctx context.Context, update func(context.Context) (bool, error)) {
44		ticker := time.NewTicker(p.interval)
45		for {
46			select {
47			case <-ctx.Done():
48				return
49			case <-ticker.C:
50				modified, err := update(ctx)
51				if err != nil {
52					p.logger.Error("error getting file system from directory", zap.Error(err))
53					continue
54				}
55	
56				if p.notify != nil {
57					p.notify(modified)
58				}
59	
60				if !modified {
61					p.logger.Debug("skipping snapshot update as it has not been modified")
62					continue
63				}
64	
65				p.logger.Debug("snapshot updated")
66			}
67		}
68	}

