 25	// SnapshotStore is an implementation of storage.SnapshotStore
 26	// This implementation is backed by a Git repository and it tracks an upstream reference.
 27	// When subscribing to this source, the upstream reference is tracked
 28	// by polling the upstream on a configurable interval.
 29	type SnapshotStore struct {
 30		logger *zap.Logger
 31		repo   *git.Repository
 32	
 33		mu   sync.RWMutex
 34		snap storage.ReadOnlyStore
 35	
 36		url             string
 37		ref             string
 38		hash            plumbing.Hash
 39		auth            transport.AuthMethod
 40		caBundle        []byte
 41		insecureSkipTLS bool
 42		pollOpts        []containers.Option[storagefs.Poller]
 43	}
 44	
 45	// WithRef configures the target reference to be used when fetching
 46	// and building fs.FS implementations.
 47	// If it is a valid hash, then the fixed SHA value is used.
 48	// Otherwise, it is treated as a reference in the origin upstream.
 49	func WithRef(ref string) containers.Option[SnapshotStore] {
 50		return func(s *SnapshotStore) {
 51			if plumbing.IsHash(ref) {
 52				s.hash = plumbing.NewHash(ref)
 53				return
 54			}
 55	
 56			s.ref = ref
 57		}
 58	}
 59	
 60	// WithPollOptions configures the poller used to trigger update procedures
 61	func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
 62		return func(s *SnapshotStore) {
 63			s.pollOpts = append(s.pollOpts, opts...)
 64		}
 65	}
 66	
