 76	// setting for the provided source.
 77	func WithInsecureTLS(insecureSkipTLS bool) containers.Option[SnapshotStore] {
 78		return func(s *SnapshotStore) {
 79			s.insecureSkipTLS = insecureSkipTLS
 80		}
 81	}
 82	
