 84	// validating the TLS connection to the provided source.
 85	func WithCABundle(caCertBytes []byte) containers.Option[SnapshotStore] {
 86		return func(s *SnapshotStore) {
 87			if caCertBytes != nil {
 88				s.caBundle = caCertBytes
 89			}
 90		}
 91	}
