 93	// NewSnapshotStore constructs and configures a Store.
 94	// The store uses the connection and credential details provided to build
 95	// fs.FS implementations around a target git repository.
 96	func NewSnapshotStore(ctx context.Context, logger *zap.Logger, url string, opts ...containers.Option[SnapshotStore]) (_ *SnapshotStore, err error) {
 97		store := &SnapshotStore{
 98			logger: logger.With(zap.String("repository", url)),
 99			url:    url,
100			ref:    "main",
101		}
102		containers.ApplyAll(store, opts...)
103	
104		field := zap.Stringer("ref", plumbing.NewBranchReferenceName(store.ref))
105		if store.hash != plumbing.ZeroHash {
106			field = zap.Stringer("SHA", store.hash)
107		}
108		store.logger = store.logger.With(field)
109	
110		store.repo, err = git.Clone(memory.NewStorage(), nil, &git.CloneOptions{
111			Auth:            store.auth,
112			URL:             store.url,
113			CABundle:        store.caBundle,
114			InsecureSkipTLS: store.insecureSkipTLS,
115		})
116		if err != nil {
117			return nil, err
118		}
119	
120		// fetch snapshot at-least once before returning store
121		// to ensure we have some state to serve
122		if err := store.get(ctx); err != nil {
123			return nil, err
124		}
125	
126		// if the reference is a static hash then it is immutable
127		// if we have already fetched it once, there is not point updating again
128		if store.hash == plumbing.ZeroHash {
129			go storagefs.
130				NewPoller(store.logger, store.pollOpts...).
131				Poll(ctx, store.update)
132		}
133	
134		return store, nil
135	}
