142	// View accepts a function which takes a *StoreSnapshot.
143	// The SnapshotStore will supply a snapshot which is valid
144	// for the lifetime of the provided function call.
145	func (s *SnapshotStore) View(fn func(storage.ReadOnlyStore) error) error {
146		s.mu.RLock()
147		defer s.mu.RUnlock()
148		return fn(s.snap)
149	}
150	
151	// update fetches from the remote and given that a the target reference
152	// HEAD updates to a new revision, it builds a snapshot and updates it
153	// on the store.
154	func (s *SnapshotStore) update(ctx context.Context) (bool, error) {
155		if err := s.repo.Fetch(&git.FetchOptions{
156			Auth: s.auth,
157			RefSpecs: []config.RefSpec{
158				config.RefSpec(fmt.Sprintf(
159					"+%s:%s",
160					plumbing.NewBranchReferenceName(s.ref),
161					plumbing.NewRemoteReferenceName("origin", s.ref),
162				)),
163			},
164		}); err != nil {
165			if !errors.Is(err, git.NoErrAlreadyUpToDate) {
166				return false, err
167			}
168	
169			return false, nil
170		}
171	
172		if err := s.get(ctx); err != nil {
173			return false, err
174		}
175	
176		return true, nil
177	}
178	
179	// get builds a new store snapshot based on the configure Git remote and reference.
180	func (s *SnapshotStore) get(context.Context) (err error) {
181		var fs fs.FS
182		if s.hash != plumbing.ZeroHash {
183			fs, err = gitfs.NewFromRepoHash(s.logger, s.repo, s.hash)
184		} else {
185			fs, err = gitfs.NewFromRepo(s.logger, s.repo, gitfs.WithReference(plumbing.NewRemoteReferenceName("origin", s.ref)))
186		}
187		if err != nil {
188			return err
189		}
190	
191		snap, err := storagefs.SnapshotFromFS(s.logger, fs)
192		if err != nil {
193			return err
194		}
195	
196		s.mu.Lock()
197		s.snap = snap
198		s.mu.Unlock()
199	
200		return nil
201	}

